import * as THREE from "three/webgpu";
import { texture, mul, float } from "three/tsl";
import gsap from "gsap";
import "@/primitives";
import "@/text";

export default function createNode(config, ctx) {
  // ---------------------------------------------------------------------------
  // Geometry & textures
  // ---------------------------------------------------------------------------
  const { position = [0, 0, 0], rotation = [0, 0, 0], scale = [1, 1, 1] } = config;
  const { imageUrl, depthMapUrl } = config.assets || {};

  const colorMap = ctx.textureLoader.load(imageUrl);
  if (colorMap) colorMap.colorSpace = THREE.SRGBColorSpace;

  const depthMap = ctx.textureLoader.load(depthMapUrl);

  // Plane aspect matches source rect (512x320 → 1.6:1)
  const geometry = new THREE.PlaneGeometry(1.6, 1, 64, 64);

  // ---------------------------------------------------------------------------
  // Node‑based material (machined‑metal look + displacement)
  // ---------------------------------------------------------------------------
  const material = new THREE.MeshStandardNodeMaterial({
    map: colorMap,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.1,
    side: THREE.DoubleSide,
  });

  // Displacement from depth map (subtle)
  material.displacementNode = mul(texture(depthMap).r, float(0.2));
  material.displacementScale = 1.0;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;

  // ---------------------------------------------------------------------------
  // Container object (position / rotation / scale from config)
  // ---------------------------------------------------------------------------
  const container = new THREE.Object3D();
  container.add(mesh);
  container.position.fromArray(position);
  container.rotation.fromArray(rotation);
  container.scale.fromArray(scale);

  // ---------------------------------------------------------------------------
  // Apply cinematic primitives defined in the node config
  // ---------------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === "function") fn(container, prim.params);
    }
  }

  // ---------------------------------------------------------------------------
  // Interaction handlers (hover lift, click emit)
  // ---------------------------------------------------------------------------
  let liftTimeline = null;
  const baseY = container.position.y;

  const handlers = {
    // hover: true → enter, false → leave
    hover: (enter) => {
      if (liftTimeline) liftTimeline.kill();
      liftTimeline = gsap.to(container.position, {
        y: baseY + (enter ? 0.15 : 0),
        duration: 0.7,
        ease: "power3.out",
      });
    },

    // click → emit event
    click: () => {
      if (typeof ctx.emit === "function") ctx.emit("hub-features.select");
    },
  };

  container.userData.handlers = handlers;

  // ---------------------------------------------------------------------------
  // Cleanup routine
  // ---------------------------------------------------------------------------
  container.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (colorMap?.dispose) colorMap.dispose();
    if (depthMap?.dispose) depthMap.dispose();
    if (liftTimeline) liftTimeline.kill();
  };

  return container;
}
